  comparison: '비교',
  risk_based: '주의사항',
  route_based: '이동·동선',
  timing_guide: '시간 계획',
  space_based_event: '행사 공간',
  faq_first: '질문 정리',
  care_guide: '관리',
  message_guide: '문구',
  product_form_comparison: '형태 비교',
