.article-grid { display: grid; grid-template-columns: minmax(0, 1fr) 280px; gap: 44px; align-items: start; }
.prose { min-width: 0; max-width: 780px; }
.prose > :first-child { margin-top: 0; }
.prose h2 { margin: 46px 0 14px; font-size: 28px; line-height: 1.32; letter-spacing: -0.025em; }
.prose h3 { margin: 32px 0 10px; font-size: 21px; }
.prose p, .prose li { color: #34423b; }
.prose strong { color: var(--ink); }
.prose ul, .prose ol { padding-left: 22px; }
.prose blockquote {
  margin: 28px 0; padding: 18px 20px; border-left: 4px solid var(--accent);
  background: var(--surface-strong); border-radius: 0 14px 14px 0;
}
.prose a { color: var(--brand); text-decoration: underline; text-underline-offset: 3px; }
.article-aside { position: sticky; top: 96px; display: grid; gap: 14px; }
.aside-card { padding: 18px; border-radius: 16px; background: var(--surface); border: 1px solid var(--line); }
.aside-card strong { display: block; margin-bottom: 6px; }
.aside-card p { margin: 0; color: var(--muted); font-size: 14px; }
.aside-card a { display: inline-block; margin-top: 12px; color: var(--brand); font-weight: 800; font-size: 14px; }
.source-list { margin-top: 56px; padding: 22px; background: var(--surface-strong); border-radius: 16px; border: 1px solid var(--line); }
.source-list h2 { margin-top: 0; font-size: 20px; }
.source-list ul { margin-bottom: 0; }

.primary-landing .article-header {
  max-width: 960px; padding: 34px; border-radius: 28px;
  background:
    radial-gradient(circle at 88% 18%, rgba(244,223,215,.92) 0 15%, transparent 16%),
    linear-gradient(145deg, #fffdf8, #edf3ee);
  border: 1px solid var(--line); box-shadow: var(--shadow);
}
.primary-landing .article-header h1 { max-width: 760px; }
.landing-quick {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin: 0 0 42px;
}
.landing-quick a {
  min-height: 170px; padding: 22px; border: 1px solid var(--line); border-radius: 18px;
  background: var(--surface); display: flex; flex-direction: column;
}
.landing-quick a:hover { transform: translateY(-2px); transition: .2s ease; box-shadow: var(--shadow); }
.landing-quick span {
  width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;
  background: var(--brand); color: white; font-size: 12px; font-weight: 900; margin-bottom: 16px;
}
.landing-quick strong { font-size: 18px; margin-bottom: 6px; }
.landing-quick small { color: var(--muted); font-size: 14px; line-height: 1.65; }

@media (max-width: 860px) {
  .article-grid { grid-template-columns: 1fr; }
  .article-aside { position: static; grid-template-columns: repeat(2, 1fr); }
  .landing-quick { grid-template-columns: 1fr; }
}
@media (max-width: 560px) {
  .article-shell { padding-top: 34px; }
  .article-aside { grid-template-columns: 1fr; }
  .primary-landing .article-header { padding: 24px; border-radius: 20px; }
}


/* ARTICLE_B_HERO_V1 */
.article-shell{
  position:relative;
  padding-top:42px;
}
.article-shell::before{
  content:"";
  position:absolute;
  z-index:0;
  left:0;
  right:0;
  top:0;
  height:330px;
  background:
    linear-gradient(90deg,
      rgba(255,249,251,.98) 0%,
      rgba(255,249,251,.95) 35%,
      rgba(255,249,251,.76) 51%,
      rgba(255,249,251,.28) 70%,
      rgba(255,249,251,.04) 86%),
    url('/images/hwaseong/hero-B-original.png') 64% center / cover no-repeat;
  border-bottom:1px solid #f7e4ea;
}
.article-shell > .container{position:relative;z-index:1;}
.article-header{
  min-height:230px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  max-width:780px;
  margin-bottom:44px;
}
.article-header p{max-width:700px;color:#5e636b;}
.article-meta span{background:rgba(255,255,255,.86);backdrop-filter:blur(4px);}
.primary-landing .article-header{
  min-height:250px;
  max-width:900px;
  padding:28px 0;
  border:0;
  box-shadow:none;
  background:transparent;
}

@media(max-width:860px){
  .article-shell::before{
    height:340px;
    background:
      linear-gradient(90deg,
        rgba(255,249,251,.98) 0%,
        rgba(255,249,251,.94) 46%,
        rgba(255,249,251,.56) 70%,
        rgba(255,249,251,.15) 100%),
      url('/images/hwaseong/hero-B-original.png') 68% center / cover no-repeat;
  }
}
@media(max-width:560px){
  .article-shell{padding-top:26px;}
  .article-shell::before{
    height:350px;
    background:
      linear-gradient(90deg,
        rgba(255,249,251,.99) 0%,
        rgba(255,249,251,.95) 60%,
        rgba(255,249,251,.57) 83%,
        rgba(255,249,251,.22) 100%),
      url('/images/hwaseong/hero-B-original.png') 72% center / cover no-repeat;
  }
  .article-header{min-height:245px;margin-bottom:34px;}
  .primary-landing .article-header{padding:18px 0;border-radius:0;}
}


/* CONTENT_ORDER_BANNERS_V2 */
.content-order-banner{
  margin:34px 0;
  padding:24px;
  width:100%;
  border:1px solid #efc7d3;
  border-radius:16px;
  background:#fff7f9;
  box-shadow:0 10px 28px rgba(52,31,40,.08);
}
.content-order-banner figcaption{font-size:21px;font-weight:800;color:#44202c;}
.content-order-banner p{margin:8px 0 18px;font-size:15px;line-height:1.6;}
.content-order-banner-actions{display:flex;flex-wrap:wrap;gap:10px;}
.content-order-banner-actions a{
  display:inline-flex;align-items:center;justify-content:center;
  min-height:48px;padding:12px 18px;border:1px solid #a82851;border-radius:10px;
  background:#fff;color:#8b1d40;font-weight:800;line-height:1.5;text-decoration:none;
}
.content-order-banner-actions a:first-child{background:#a82851;color:#fff;}
.content-order-banner-actions a:focus-visible{outline:3px solid #44202c;outline-offset:3px;}
@media(max-width:620px){
  .content-order-banner{margin:26px 0;padding:20px;border-radius:12px;}
  .content-order-banner-actions a{flex:1 1 180px;}
}


/* SITE_FACTORY_INFORMATION_ARCHITECTURE_V2 */
.article-grid-single{grid-template-columns:minmax(0,900px);max-width:900px;}
.source-list-head{display:flex;justify-content:space-between;gap:18px;align-items:baseline;margin-bottom:14px;}
.source-list-head h2{margin:0;}
.source-list-head>span{color:var(--muted);font-size:13px;}
.source-list ul{list-style:none;padding:0;margin:0;display:grid;gap:10px;}
.source-list li{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:12px 0;border-top:1px solid var(--line);}
.source-list li:first-child{border-top:0;}
.source-list li strong{display:block;color:var(--ink);font-size:14px;}
.source-list li span{display:block;color:var(--muted);font-size:12px;margin-top:2px;}
.source-list li>a{flex:0 0 auto;font-size:13px;font-weight:800;}
.related-questions{margin-top:54px;padding-top:38px;border-top:1px solid var(--line);}
.related-questions-head{max-width:760px;margin-bottom:22px;}
.related-questions-head h2{margin:10px 0 8px;font-size:30px;letter-spacing:-.03em;}
.related-questions-head p{margin:0;color:var(--muted);}
.related-question-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;}
.related-question-card{min-height:210px;padding:22px;border:1px solid var(--line);border-radius:16px;background:var(--surface);display:flex;flex-direction:column;}
.related-question-card>span{font-size:12px;font-weight:900;color:var(--accent);}
.related-question-card>strong{margin:8px 0;font-size:18px;line-height:1.4;}
.related-question-card>p{margin:0;color:var(--muted);font-size:14px;}
.related-question-card>b{margin-top:auto;padding-top:18px;color:var(--brand);font-size:13px;}
.landing-quick{grid-template-columns:repeat(4,1fr);}
@media(max-width:900px){.landing-quick{grid-template-columns:repeat(2,1fr);}}
@media(max-width:620px){
  .source-list-head,.source-list li{display:block;}
  .source-list-head>span{display:block;margin-top:4px;}
  .source-list li>a{display:inline-block;margin-top:7px;}
  .related-question-grid,.landing-quick{grid-template-columns:1fr;}
}

